{
  "category_edits": [
    {
      "category": "hyperparameter_tuning",
      "rationale": "Across all four category models, couple a smaller learning rate with stronger dropout and weight decay to test whether gentler updates and regularization improve validation ranking under full-catalog cross-entropy. Preserve the existing Adam optimizer, architecture, loss, inference, seeds and training caps. Dropout is already passed explicitly during training; prediction disables dropout, so predictor and checkpoint shapes remain consistent.",
      "edits": [
        {
          "find": "DROPOUT_RATE  = float(os.environ.get(\"BERT4REC_DROPOUT\", \"0.2\"))",
          "replace": "DROPOUT_RATE  = float(os.environ.get(\"BERT4REC_DROPOUT\", \"0.3\"))"
        },
        {
          "find": "LR            = float(os.environ.get(\"BERT4REC_LR\", \"1e-3\"))",
          "replace": "LR            = float(os.environ.get(\"BERT4REC_LR\", \"5e-4\"))"
        },
        {
          "find": "WEIGHT_DECAY  = float(os.environ.get(\"BERT4REC_WD\", \"0.0\"))",
          "replace": "WEIGHT_DECAY  = float(os.environ.get(\"BERT4REC_WD\", \"1e-5\"))"
        }
      ]
    }
  ],
  "change_summary": "Jointly tune all four BERT4Rec category models: learning rate 5e-4, dropout 0.3 and weight decay 1e-5. Retain one checkpoint per category and all other behavior."
}
